/*selectMasterMdCmCatalogRegReqList*/ SELECT NVL((SELECT ITEM_FLAG FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO), 'I') AS ITEM_FLAG, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTTP' AND CODE = NVL((SELECT ITEM_FLAG FROM ICOMBYIT WHERE BUYER = A.BUYER AND BUYER_ITEM_NO = A.BUYER_ITEM_NO), 'I')) AS ITEM_FLAG_TEXT, A.REQ_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTREQ' AND CODE = A.REQ_TYPE) AS REQ_TYPE_TEXT, A.SEQ, A.ADD_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.ADD_USER_ID) AS ADD_USER_NAME, TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD HH24:MI:SS') AS ADD_DATE, A.BUYER, A.CONTRACT_NO, A.CONTRACT_SEQ, A.BUYER_ITEM_NO, A.ANOTHER_OFFER_FLAG, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'PRDTREP' AND CODE = A.ANOTHER_OFFER_FLAG) AS ANOTHER_OFFER_FLAG_TEXT, A.ANOTHER_OFFER_NOTE, A.CATEGORY_NO, (SELECT CATEG_NAME FROM ICOMBYCA WHERE STD_CATEG_ID = A.CATEGORY_NO AND COM_CODE = A.BUYER) AS CATEG_NAME, A.DESCRIPTION, A.SPECIFICATION, A.MAKER_PART_NO, A.AGENT_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT_CODE) AS AGENT_CODE_TEXT, A.UNIT_MEASURE, A.UNIT_PRICE, A.LIST_PRICE, A.DELIVERY_LT, A.REMARK, A.IMGFILE_NAME, A.IMGFILE_DIR, A.BELOW_COMORG_CODE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BELOW_COMORG_CODE) AS BUYER_TEXT, A.PROCESS_TYPE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = A.PROCESS_TYPE) AS PROCESS_TYPE_TEXT, A.ORIGIN_CODE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = A.ORIGIN_CODE) AS ORIGIN_CODE_TEXT, A.ORIGIN_AGENT, A.PRODUCT_CLOSE_FLAG, A.SELLER_ITEM_NO, A.MAKER_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M104' AND CODE = A.MAKER_CODE) AS MAKER_CODE_TEXT, A.CMS_CATEG_ID, (SELECT CATEG_NAME FROM CMSCATEG WHERE CMS_CATEG_ID = A.CMS_CATEG_ID) AS CMS_CATEG_TEXT, A.CMS_CATLG_ID, A.KEP_DESCRIPTION, A.KEP_SPECIFICATION, A.KEP_UNIT_MEASURE, A.KEP_MAKER_NAME, A.KEP_ORIGIN_NAME, A.KEP_MAKER_PART_NO, A.KEP_MAKER_CODE, A.KEP_ORIGIN_CODE, A.ITEM_MAKE_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = A.ITEM_MAKE_TYPE) AS ITEM_MAKE_TYPE_TEXT, A.TO_DATE, (SELECT DECODE(COUNT(*), 0, 'N', 'Y') FROM KEP_BUYER_ORG_MNG WHERE ORG_CODE = (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'PFMP' AND COMPANY_CODE = 'KRKORE0001' AND CODE = A.BELOW_COMORG_CODE AND FLAG = 'Y')) AS PROFILE_YN, A.BUY_CLOSE_DATE, A.MIN_ORDER_QTY, A.PUR_UNIT_QTY, A.SELLER_AREA, A.TAX_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'TX17' AND CODE = A.TAX_TYPE) AS TAX_TYPE_TEXT, A.DESCRIPTION_ENG, A.SPECIFICATION_ENG, A.CHANGE_USER_ID, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NAME, TO_CHAR(A.CHANGE_DATE, 'YYYY/MM/DD HH24:MI:SS') AS CHANGE_DATE, BUY_GREEN_ITEM_NM, BUY_GREEN_ITEM_CNO, BUY_GREEN_ITEM_FROM_DATE, BUY_GREEN_ITEM_TO_DATE FROM KEP_CA_REQ_IMSI A WHERE 1=1 AND A.ADD_USER_ID = #{st_user_id}
AND A.BELOW_COMORG_CODE = #{st_buyer_code}
AND A.BUYER_ITEM_NO LIKE '%' || UPPER(#{st_buyer_item_no}) || '%'
AND A.DESCRIPTION LIKE '%' || UPPER(#{st_description}) || '%'
AND A.SPECIFICATION LIKE '%' || UPPER(#{st_specification}) || '%'
ORDER BY SEQ

mapper.update:

DELETE	KEP_CA_REQ_IMSI
WHERE	1=1
AND		REQ_TYPE = #{REQ_TYPE}
AND		BUYER = #{BUYER}
AND		SEQ = #{SEQ}
AND		BUYER_ITEM_NO = #{BUYER_ITEM_NO}
AND		ADD_USER_ID = #{st_user_id}

SELECT NVL(MAX(SEQ),0)+1 AS SEQ FROM KEP_CA_REQ_IMSI WHERE BUYER = #{BUYER}
/*batchMasterMdCmCatalogRegReNew*/ INSERT INTO KEP_CA_REQ_IMSI ( REQ_TYPE, BUYER, SEQ, BUYER_ITEM_NO, ANOTHER_OFFER_FLAG, ANOTHER_OFFER_NOTE, CATEGORY_NO, DESCRIPTION, SPECIFICATION, MAKER_PART_NO, AGENT_CODE, UNIT_MEASURE, UNIT_PRICE, LIST_PRICE, DELIVERY_LT, REMARK, CONTRACT_NO, CONTRACT_SEQ, IMGFILE_NAME, IMGFILE_DIR, BELOW_COMORG_CODE, PROCESS_TYPE, ORIGIN_CODE, ORIGIN_AGENT, PRODUCT_CLOSE_FLAG, SELLER_ITEM_NO, MAKER_CODE, CMS_CATEG_ID, CMS_CATLG_ID, KEP_DESCRIPTION, KEP_SPECIFICATION, KEP_UNIT_MEASURE, KEP_MAKER_NAME, KEP_ORIGIN_NAME, KEP_MAKER_PART_NO, KEP_MAKER_CODE, KEP_ORIGIN_CODE, ITEM_MAKE_TYPE, TO_DATE, BUY_CLOSE_DATE, MIN_ORDER_QTY, PUR_UNIT_QTY, SELLER_AREA, TAX_TYPE, DESCRIPTION_ENG, SPECIFICATION_ENG, ADD_USER_ID, ADD_DATE, CHANGE_USER_ID, CHANGE_DATE, BUY_GREEN_ITEM_NM, BUY_GREEN_ITEM_CNO, BUY_GREEN_ITEM_FROM_DATE, BUY_GREEN_ITEM_TO_DATE ) ( SELECT #{REQ_TYPE}, #{BUYER}, #{SEQ}, #{BUYER_ITEM_NO}, #{ANOTHER_OFFER_FLAG}, #{ANOTHER_OFFER_NOTE}, B.CATEGORY_NO, B.DESCRIPTION_LOC, B.SPECIFICATION, B.MAKER_PART_NO, C.AGENT, C.UNIT_MEASURE, C.UNIT_PRICE, C.LIST_PRICE, TO_CHAR(C.DELIVERY_LT), B.REMARK, #{CONTRACT_NO}, NVL(#{CONTRACT_SEQ}, 'XX'), B.IMGFILE_NAME, B.IMGFILE_DIR, C.BELOW_COMORG_CODE, C.PROCESS_TYPE, C.ORIGIN_CODE, C.ORIGIN_AGENT, B.PRODUCT_CLOSE_FLAG, C.SELLER_ITEM_NO, C.MAKER_CODE, B.CMS_CATEG_ID, B.CMS_CATLG_ID, B.KEP_DESCRIPTION, B.KEP_SPECIFICATION, B.KEP_UNIT_MEASURE, B.KEP_MAKER_NAME, B.KEP_ORIGIN_NAME, B.KEP_MAKER_PART_NO, B.KEP_MAKER_CODE, B.KEP_ORIGIN_CODE, C.ITEM_MAKE_TYPE, C.SELL_CLOSE_DATE, C.BUY_CLOSE_DATE, C.MIN_ORDER_QTY, C.PUR_UNIT_QTY, C.SELLER_AREA, B.TAX_TYPE, B.DESCRIPTION_ENG, B.SPECIFICATION_ENG, #{st_user_id}, SYSDATE, #{st_user_id}, SYSDATE, B.BUY_GREEN_ITEM_NM, B.BUY_GREEN_ITEM_CNO, B.BUY_GREEN_ITEM_FROM_DATE, B.BUY_GREEN_ITEM_TO_DATE FROM ( SELECT #{BUYER} AS BUYER, #{BUYER_ITEM_NO} AS BUYER_ITEM_NO, #{CONTRACT_NO} AS CONTRACT_NO, #{CONTRACT_SEQ} AS CONTRACT_SEQ FROM DUAL ) A, ICOMBYIT B, ICOMCQDT C
WHERE 1=1 AND B.BUYER(+) = C.BUYER AND B.BUYER_ITEM_NO(+) = C.BUYER_ITEM_NO AND A.BUYER = #{BUYER} AND A.CONTRACT_NO = #{CONTRACT_NO} AND A.CONTRACT_SEQ = #{CONTRACT_SEQ} AND A.BUYER_ITEM_NO = #{BUYER_ITEM_NO} AND A.BUYER = C.BUYER(+) AND A.CONTRACT_NO = C.CONTRACT_NO(+) AND A.CONTRACT_SEQ = C.CONTRACT_SEQ(+) AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO(+) )
